import 'dart:ffi';
import 'dart:io';
import 'package:ffi/ffi.dart';
import 'package:microphone_dart/microphone_dart.dart';

// Every loaded module named [name] (Windows: the process module list).
List<String> windowsModules(String name) {
  final kernel32 = DynamicLibrary.open('kernel32.dll');
  final process = kernel32.lookupFunction<IntPtr Function(), int Function()>('GetCurrentProcess');
  final enumModules = kernel32.lookupFunction<Int32 Function(IntPtr, Pointer<IntPtr>, Uint32, Pointer<Uint32>), int Function(int, Pointer<IntPtr>, int, Pointer<Uint32>)>('K32EnumProcessModules');
  final fileName = kernel32.lookupFunction<Uint32 Function(IntPtr, Pointer<Utf16>, Uint32), int Function(int, Pointer<Utf16>, int)>('GetModuleFileNameW');
  const capacity = 4096, pathCapacity = 32768;
  final modules = calloc<IntPtr>(capacity), needed = calloc<Uint32>(), path = calloc<Uint16>(pathCapacity).cast<Utf16>();
  try {
    if (enumModules(process(), modules, capacity * sizeOf<IntPtr>(), needed) == 0) throw StateError('K32EnumProcessModules failed');
    final count = needed.value ~/ sizeOf<IntPtr>();
    if (count > capacity) throw StateError('module list truncated: $count');
    final found = <String>[];
    for (var i = 0; i < count; i++) {
      final length = fileName(modules[i], path, pathCapacity);
      if (length == 0 || length >= pathCapacity) throw StateError('GetModuleFileNameW failed');
      final value = path.toDartString(length: length);
      if (value.split(r'\').last.toLowerCase() == name) found.add(value);
    }
    return found;
  } finally {
    calloc.free(modules); calloc.free(needed); calloc.free(path);
  }
}

String windowsPath(String path) => (path.startsWith(r'\\?\') ? path.substring(4) : path).toLowerCase();

// The exact bundled file, and only it, is the loaded library.
void expectExactLibrary(String expected) {
  if (Platform.isWindows) {
    final modules = windowsModules('microphone.dll');
    if (modules.length != 1 || windowsPath(modules.single) != windowsPath(expected)) throw StateError('unexpected native module: $modules');
    return;
  }
  final mappings = File('/proc/self/maps').readAsLinesSync().where((line) => line.contains('libmicrophone.so')).toList();
  if (mappings.isEmpty || mappings.any((line) => !line.endsWith(' $expected'))) throw StateError('unexpected native mapping: $mappings');
}

// Device-free C ABI: version, permission state and recorder lifecycle. No
// capture is started and no input device is enumerated or opened.
void checkAbi(String path) {
  final lib = DynamicLibrary.open(path);
  final abiVersion = lib.lookupFunction<Uint32 Function(), int Function()>('microphone_abi_version');
  final permissionStatus = lib.lookupFunction<Int32 Function(), int Function()>('microphone_permission_status');
  final recorderNew = lib.lookupFunction<Pointer<Void> Function(), Pointer<Void> Function()>('microphone_recorder_new');
  final recorderFree = lib.lookupFunction<Void Function(Pointer<Void>), void Function(Pointer<Void>)>('microphone_recorder_free');
  final state = lib.lookupFunction<Int32 Function(Pointer<Void>, Uint64), int Function(Pointer<Void>, int)>('microphone_state');
  final sampleRate = lib.lookupFunction<Int32 Function(Pointer<Void>, Uint64), int Function(Pointer<Void>, int)>('microphone_sample_rate');
  final recordingFree = lib.lookupFunction<Int32 Function(Pointer<Void>, Uint64), int Function(Pointer<Void>, int)>('microphone_recording_free');
  final lastError = lib.lookupFunction<Pointer<Utf8> Function(), Pointer<Utf8> Function()>('microphone_last_error');
  if (abiVersion() != 3) throw StateError('unexpected ABI version ${abiVersion()}');
  // Linux and Windows do not gate capture: "not applicable", no OS prompt.
  if (permissionStatus() != 0) throw StateError('unexpected permission state ${permissionStatus()}');
  // Creating a recorder resolves the OS audio library; no device is opened.
  final recorder = recorderNew();
  if (recorder == nullptr) throw StateError('microphone_recorder_new failed: ${lastError().toDartString()}');
  if (state(recorder, 1) != -1 || sampleRate(recorder, 1) != -1 || recordingFree(recorder, 1) != -1) throw StateError('unknown recording contract');
  if (state(nullptr, 1) != -1 || recordingFree(nullptr, 1) != -1) throw StateError('null recorder contract');
  recorderFree(recorder);
  recorderFree(nullptr);
}

Future<void> main() async {
  final expected = File(Platform.environment['MICROPHONE_LIB']!).resolveSymbolicLinksSync();
  final backend = Microphone.backend;
  if (backend.name != 'ffi') throw StateError('native backend did not load');
  await backend.initialize();
  expectExactLibrary(expected);
  checkAbi(expected);
  if (!await backend.hasPermission()) throw StateError('permission unexpectedly denied');
  await backend.dispose();
  await Microphone.reset();
  expectExactLibrary(expected);
  print('Exact native library loaded ($expected); ABI version, permission state, recorder initialization and disposal passed without capture or device enumeration');
}
